const data = require('fs').readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length > 0);

function main() {
    let idx = 0;
    let count = 0;
    const n = parseInt(data[idx++], 10);
    const str = data[idx++];
    for (let i = 0; i < n; i++) {
        if (str[i] === 'x' && str[i + 1] === 'x' && str[i + 2] === 'x')
            count++;
    }
    process.stdout.write(String(count));
}

main();
